      "n_max": 100000,
      "characters": "Only uppercase A, C, G, T",
      "note": "Since there are only 4 distinct characters, the maximum possible answer is 4."
    },
    "examples": [
      {
        "input": "dna = \"ACGTATCG\"",
        "output": "5",
