        "code": "def longest_pure_segment(dna):\n    last_seen = {}   # maps character to its most recent index\n    left = 0         # left boundary of the current window\n    max_len = 0\n\n    for right in range(len(dna)):\n        char = dna[right]\n        # If char was seen and its last occurrence is within the window,\n        # move left past that occurrence to maintain uniqueness\n        if char in last_seen and last_seen[char] >= left:\n            left = last_seen[char] + 1\n\n        last_seen[char] = right                   # update most recent index\n        max_len = max(max_len, right - left + 1)  # update best window size\n\n    return max_len",
