      },
      {
        "input": "profits = [-1, 3, 3, -1, 3, 3]",
        "output": "(11, 1, 5)",
        "explanation": "The subarray [3, 3, -1, 3, 3] from index 1 to index 5 sums to 3+3+(-1)+3+3 = 11. The subarray from index 0 to 5 sums to -1+3+3-1+3+3 = 10, which is less."
      }
