    "solution": {
      "brute_force": {
        "approach": "Try every possible subarray by iterating over all start indices i and all end indices j >= i. Compute the sum and track the maximum. This is O(n^2) and is suitable only for small inputs.",
        "code": "def max_profit_subarray(profits):\n    n = len(profits)\n    max_sum = profits[0]\n    best_start = 0\n    best_end = 0\n\n    for i in range(n):\n        current_sum = 0\n        for j in range(i, n):\n            current_sum += profits[j]\n            # Update only if strictly greater (earliest start/end on tie)\n            if current_sum > max_sum:\n                max_sum = current_sum\n                best_start = i\n                best_end = j\n\n    return (max_sum, best_start, best_end)",
        "time": "O(n^2) — two nested loops",
        "space": "O(1) extra"
